export const runtime_settingsSchema = {"$schema":"http://json-schema.org/draft-07/schema#","definitions":{"AgentSettings":{"description":"Runtime-configurable local agent settings.","properties":{"completion":{"allOf":[{"$ref":"#/definitions/CompletionSettings"}],"default":{"max_tokens":null,"parallel_tool_calls":null,"prompt_cache":null,"reasoning_effort":null,"seed":null,"stop":[],"temperature":null,"tool_choice":{"mode":"auto"},"top_p":null},"description":"Sampling / generation parameters."},"hooks":{"allOf":[{"$ref":"#/definitions/HookSettings"}],"default":{"enabled":true,"log":""},"description":"Observable lifecycle hooks."},"max_steps":{"default":50,"description":"Maximum model/tool steps per turn (`1..=200`; default 50).","format":"uint","minimum":0.0,"type":"integer"},"memory":{"allOf":[{"$ref":"#/definitions/MemorySettings"}],"default":{"dir":"","enabled":true},"description":"Multi-turn conversation memory."}},"type":"object"},"CompletionSettings":{"description":"Sampling / generation parameters for the local agent.","properties":{"max_tokens":{"default":null,"description":"Output-token cap; omitted keeps the provider default.","format":"uint64","minimum":0.0,"type":["integer","null"]},"parallel_tool_calls":{"default":null,"description":"Whether the provider may run tool calls in parallel.","type":["boolean","null"]},"prompt_cache":{"default":null,"description":"Prompt-cache retention: `short|long`.","type":["string","null"]},"reasoning_effort":{"default":null,"description":"Portable reasoning effort: `minimal|low|medium|high|xhigh|max`.","type":["string","null"]},"seed":{"default":null,"description":"Sampling seed for reproducible runs.","format":"uint64","minimum":0.0,"type":["integer","null"]},"stop":{"default":[],"description":"Stop sequences.","items":{"type":"string"},"type":"array"},"temperature":{"default":null,"description":"Sampling temperature (`0.0..=2.0`); omitted keeps the provider default.","format":"double","type":["number","null"]},"tool_choice":{"allOf":[{"$ref":"#/definitions/ToolChoiceSetting"}],"default":{"mode":"auto"},"description":"Tool-selection policy."},"top_p":{"default":null,"description":"Nucleus sampling (`0.0..=1.0`); omitted keeps the provider default.","format":"double","type":["number","null"]}},"type":"object"},"HookSettings":{"description":"Observable agent lifecycle hooks configuration.","properties":{"enabled":{"default":true,"description":"Whether lifecycle hook events are emitted.","type":"boolean"},"log":{"default":"","description":"Optional JSONL file that receives the hook events (append-only).","type":"string"}},"type":"object"},"MemorySettings":{"description":"Multi-turn conversation memory for the local agent.","properties":{"dir":{"default":"","description":"Memory directory; empty means `$ZEOKEEL_HOME/agent-memory`.","type":"string"},"enabled":{"default":true,"description":"Whether conversation memory is enabled.","type":"boolean"}},"type":"object"},"ToolChoiceSetting":{"description":"How the model may choose tools for a turn.","oneOf":[{"description":"The model decides (default).","properties":{"mode":{"enum":["auto"],"type":"string"}},"required":["mode"],"type":"object"},{"description":"No tool may be called.","properties":{"mode":{"enum":["none"],"type":"string"}},"required":["mode"],"type":"object"},{"description":"At least one tool must be called.","properties":{"mode":{"enum":["required"],"type":"string"}},"required":["mode"],"type":"object"},{"description":"Only the listed tools may be called.","properties":{"mode":{"enum":["specific"],"type":"string"},"tools":{"items":{"type":"string"},"type":"array"}},"required":["mode","tools"],"type":"object"}]},"ToolSettings":{"description":"Tool execution and approval-wait timeouts for the local agent.","properties":{"approval_timeout_ms":{"default":300000,"description":"Approval wait timeout in milliseconds (1000..=1800000).","format":"uint64","minimum":0.0,"type":"integer"},"tool_timeout_ms":{"default":120000,"description":"Per-tool-call timeout in milliseconds (1000..=600000).","format":"uint64","minimum":0.0,"type":"integer"}},"type":"object"}},"description":"Non-secret settings snapshot published to the local agent runtime.\n\nDeliberately contains no `ProviderConfig`: provider credentials/base URLs are host/secret-store concerns and must never be readable by every package linked against the config contract (review round-3 P2). Only the sections the runtime needs on each turn are published.","properties":{"agent":{"allOf":[{"$ref":"#/definitions/AgentSettings"}],"default":{"completion":{"max_tokens":null,"parallel_tool_calls":null,"prompt_cache":null,"reasoning_effort":null,"seed":null,"stop":[],"temperature":null,"tool_choice":{"mode":"auto"},"top_p":null},"hooks":{"enabled":true,"log":""},"max_steps":50,"memory":{"dir":"","enabled":true}},"description":"Runtime agent settings (completion/memory/hooks/max_steps)."},"tools":{"allOf":[{"$ref":"#/definitions/ToolSettings"}],"default":{"approval_timeout_ms":300000,"tool_timeout_ms":120000},"description":"Tool execution / approval-wait timeouts."}},"title":"RuntimeSettings","type":"object"} as const;

